begin;
create extension if not exists pgtap with schema extensions;
set local search_path = extensions, public, pg_catalog;
select plan(16);
select ok(not has_function_privilege('anon','public.customer_booking(text,jsonb)','EXECUTE'),'guest cannot call database gateway directly');
select ok(not has_function_privilege('authenticated','public.customer_booking(text,jsonb)','EXECUTE'),'staff cannot call server gateway directly');
select ok(has_function_privilege('service_role','public.customer_booking(text,jsonb)','EXECUTE'),'server can call gateway');
select ok(not (select prosecdef from pg_proc where oid='public.customer_booking(text,jsonb)'::regprocedure),'gateway does not elevate database privileges');
select ok(exists(select 1 from pg_trigger where tgrelid='public.bookings'::regclass and tgname='guard_bookings_against_new_overlaps' and tgenabled='O'),'database guards simultaneous overlapping appointments without changing legacy records');
-- Isolate working hours from the fixture weekday. All mutations roll back.
update public.branches set working_hours=(select jsonb_object_agg(day,jsonb_build_object('open','09:00','close','21:00','closed',false)) from unnest(array['monday','tuesday','wednesday','thursday','friday','saturday','sunday']) day) where id='10000000-0000-4000-8000-000000000012';
update public.barbers set vacations='[]',time_offs='[]' where id='30000000-0000-4000-8000-000000000121';
select set_config('booking.selection',jsonb_build_object('branch_id','10000000-0000-4000-8000-000000000012','barber_id','30000000-0000-4000-8000-000000000121','service_ids',jsonb_build_array('20000000-0000-4000-8000-000000000121'),'date',((current_timestamp at time zone 'Asia/Kuwait')::date+1))::text,true);
select is((public.customer_booking('slots',current_setting('booking.selection')::jsonb)->>'duration')::integer,30,'duration comes from assigned service');
select is((public.customer_booking('slots',current_setting('booking.selection')::jsonb)->>'price')::numeric,5::numeric,'price comes from assigned service');
select ok(jsonb_array_length(public.customer_booking('slots',current_setting('booking.selection')::jsonb)->'slots')>0,'working day has slots');
select throws_ok($$select public.customer_booking('slots',current_setting('booking.selection')::jsonb||'{"branch_id":"10000000-0000-4000-8000-000000000013"}')$$,'P0001','INVALID_SELECTION','cross-branch barber rejected');
select throws_ok($$select public.customer_booking('slots',current_setting('booking.selection')::jsonb||'{"service_ids":["20000000-0000-4000-8000-000000000123"]}')$$,'P0001','INVALID_SELECTION','unassigned service rejected');
select throws_ok($$select public.customer_booking('slots',current_setting('booking.selection')::jsonb||'{"service_ids":["20000000-0000-4000-8000-000000000121","20000000-0000-4000-8000-000000000121"]}')$$,'P0001','INVALID_SELECTION','duplicate services rejected');
select throws_ok($$select public.customer_booking('slots',current_setting('booking.selection')::jsonb||jsonb_build_object('date',((current_timestamp at time zone 'Asia/Kuwait')::date-1)))$$,'P0001','INVALID_DATE','past date rejected');
select throws_ok($$select public.customer_booking('slots',current_setting('booking.selection')::jsonb||jsonb_build_object('date',((current_timestamp at time zone 'Asia/Kuwait')::date+100)))$$,'P0001','INVALID_DATE','booking window enforced');
update public.barbers set vacations=jsonb_build_array(jsonb_build_object('startDate',current_setting('booking.selection')::jsonb->>'date','endDate',current_setting('booking.selection')::jsonb->>'date')) where id='30000000-0000-4000-8000-000000000121';
select is(public.customer_booking('slots',current_setting('booking.selection')::jsonb)->'slots','[]'::jsonb,'vacation removes slots');
update public.barbers set vacations='[]',time_offs=jsonb_build_array(jsonb_build_object('type','one-time','date',current_setting('booking.selection')::jsonb->>'date','start','09:00','end','21:00')) where id='30000000-0000-4000-8000-000000000121';
select is(public.customer_booking('slots',current_setting('booking.selection')::jsonb)->'slots','[]'::jsonb,'time off removes overlapping slots');
update public.barbers set time_offs='[]' where id='30000000-0000-4000-8000-000000000121';
update public.branches set working_hours=(select jsonb_object_agg(day,jsonb_build_object('open','09:00','close','21:00','closed',true)) from unnest(array['monday','tuesday','wednesday','thursday','friday','saturday','sunday']) day) where id='10000000-0000-4000-8000-000000000012';
select is(public.customer_booking('slots',current_setting('booking.selection')::jsonb)->'slots','[]'::jsonb,'branch closure removes slots');
select * from finish();
rollback;
